import type { ReadableStream } from 'web-streams-polyfill';

import { MEMORY_DOWNLOAD_LIMIT } from '@proton/shared/lib/drive/constants';
import downloadFile from '@proton/shared/lib/helpers/downloadFile';

import type { TransferMeta } from '../../../components/TransferManager/transfer';
import { TransferCancel } from '../../../components/TransferManager/transfer';
import { EnrichedError } from '../../../utils/errorHandling/EnrichedError';
import { isValidationError } from '../../../utils/errorHandling/ValidationError';
import { streamToBuffer } from '../../../utils/stream';
import { Actions, countActionWithTelemetry } from '../../../utils/telemetry';
import { isTransferCancelError } from '../../../utils/transfer';
import type { LogCallback } from '../interface';
import { initDownloadSW, openDownloadStream } from './download';

// FileSaver provides functionality to start download to file. This class does
// not deal with API or anything else. Files which fit the memory (see
// MEMORY_DOWNLOAD_LIMIT constant) are buffered in browser and then saved in
// one go. Bigger files are streamed and user can see the progress almost like
// it would be normal file. See saveViaDownload for more info.
class FileSaver {
    private useBlobFallback = false;

    private swFailReason?: string;

    constructor() {
        initDownloadSW().catch((error) => {
            this.useBlobFallback = true;
            console.warn('Saving file will fallback to in-memory downloads:', error.message);
            this.swFailReason = error.message;
        });
    }

    // saveViaDownload uses service workers to download file without need to
    // buffer the whole content in memory and open the download in browser as
    // is done for regular files. To do this, using service worker is used
    // local new address where is streamed the download and that address is
    // opened as hidden iframe in the main page to start download in browser.
    // To have this working, service workers and option to return stream as
    // the response is needed, which is not supported by all browsers. See
    // isUnsupported in download.ts for more info. When the support is missing,
    // it falls back to buffered download.
    // Ideally, once we update to openpgpjs v5 with custom web workers, would
    // be great if we could merge this to the same worker (but note the
    // difference between web and service worker) to reduce data exchanges.
    private async saveViaDownload(stream: ReadableStream<Uint8Array>, meta: TransferMeta, log: LogCallback) {
        if (this.useBlobFallback) {
            void countActionWithTelemetry(Actions.DownloadFallback);
            return this.saveViaBuffer(stream, meta, log);
        } else {
            void countActionWithTelemetry(Actions.DownloadUsingSW);
        }

        log('Saving via service worker');

        try {
            const abortController = new AbortController();
            const saveStream = await openDownloadStream(meta, { onCancel: () => abortController.abort() });
            await new Promise((resolve, reject) => {
                abortController.signal.addEventListener('abort', () => {
                    reject(new TransferCancel({ message: `Transfer canceled` }));
                });
                stream.pipeTo(saveStream, { preventCancel: true }).then(resolve).catch(reject);
            });
        } catch (err: any) {
            log(`Save via download failed. Reason: ${err.message}`);
            throw err;
        }
    }

    // saveViaBuffer reads the stream and downloads the file in one go.
    // eslint-disable-next-line class-methods-use-this
    private async saveViaBuffer(stream: ReadableStream<Uint8Array>, meta: TransferMeta, log: LogCallback) {
        log('Saving via buffer');
        try {
            const chunks = await streamToBuffer(stream);
            downloadFile(new Blob(chunks, { type: meta.mimeType }), meta.filename);
        } catch (err: any) {
            log(`Save via buffer failed. Reason: ${err.message}`);
            if (!isTransferCancelError(err)) {
                if (isValidationError(err)) {
                    throw err;
                }

                if (err instanceof EnrichedError) {
                    throw err;
                }

                throw new EnrichedError(`Download failed: ${err.message || err}`, {
                    extra: { err },
                });
            }
        }
    }

    async saveAsFile(stream: ReadableStream<Uint8Array>, meta: TransferMeta, log: LogCallback) {
        log(
            `Saving file. meta size: ${meta.size}, memory limit: ${MEMORY_DOWNLOAD_LIMIT}, will use blob fallback: ${this.useBlobFallback}`
        );
        if (this.swFailReason) {
            log(`Service worker fail reason: ${this.swFailReason}`);
        }
        if (meta.size && meta.size < MEMORY_DOWNLOAD_LIMIT) {
            return this.saveViaBuffer(stream, meta, log);
        }
        return this.saveViaDownload(stream, meta, log);
    }

    isFileTooBig(size: number) {
        return this.useBlobFallback && size > MEMORY_DOWNLOAD_LIMIT;
    }
}

export default new FileSaver();

import { useRef, useState } from 'react';

import metrics from '@proton/metrics';
import type { HttpsProtonMeDriveDownloadErrorsTotalV2SchemaJson } from '@proton/metrics/types/drive_download_errors_total_v2.schema';
import {
    getIsNetworkError,
    getIsOfflineError,
    getIsTimeoutError,
    getIsUnreachableError,
} from '@proton/shared/lib/api/helpers/apiErrorHelper';
import type { UserModel } from '@proton/shared/lib/interfaces';

import { TransferState } from '../../../components/TransferManager/transfer';
import { isAbortError, isIgnoredErrorForReporting, sendErrorReport } from '../../../utils/errorHandling';
import { is4xx, is5xx, isCryptoEnrichedError } from '../../../utils/errorHandling/apiErrors';
import { getIsPublicContext } from '../../../utils/getIsPublicContext';
import { UserAvailabilityTypes } from '../../../utils/metrics/types/userSuccessMetricsTypes';
import { userSuccessMetrics } from '../../../utils/metrics/userSuccessMetrics';
import type { DownloadErrorCategoryType, MetricShareTypeWithPublic } from '../../../utils/type/MetricTypes';
import { MetricSharePublicType } from '../../../utils/type/MetricTypes';
import { DownloadErrorCategory } from '../../../utils/type/MetricTypes';
import useSharesState from '../../_shares/useSharesState';
import { getShareType } from '../../_uploads/UploadProvider/useUploadMetrics';
import type { Download } from './interface';

const REPORT_ERROR_USERS_EVERY = 5 * 60 * 1000; // 5 minutes

export function getErrorCategory(state: TransferState, error: any): DownloadErrorCategoryType {
    if (getIsUnreachableError(error) || getIsTimeoutError(error)) {
        return DownloadErrorCategory.ServerError;
    } else if (getIsOfflineError(error) || getIsNetworkError(error) || state === TransferState.NetworkError) {
        return DownloadErrorCategory.NetworkError;
    } else if (error?.statusCode && error?.statusCode === 429) {
        return DownloadErrorCategory.RateLimited;
    } else if (isCryptoEnrichedError(error)) {
        return DownloadErrorCategory.DecryptionError;
    } else if (error?.statusCode && is4xx(error?.statusCode)) {
        return DownloadErrorCategory.HTTPClientError;
    } else if (error?.statusCode && is5xx(error?.statusCode)) {
        return DownloadErrorCategory.HTTPServerError;
    }

    sendErrorReport(error, {
        tags: {
            label: 'download-unknown-error',
        },
    });

    return DownloadErrorCategory.Unknown;
}

const getKey = (downloadId: string, retries: number) => `${downloadId}-${retries}`;

export const useDownloadMetrics = (
    initiator: HttpsProtonMeDriveDownloadErrorsTotalV2SchemaJson['Labels']['initiator'],
    user?: UserModel
) => {
    const { getShare } = useSharesState();
    const [processed, setProcessed] = useState<Set<string>>(new Set());
    const lastErroringUserReport = useRef(0);

    const getShareIdType = (shareId: string): MetricShareTypeWithPublic => {
        const share = getShare(shareId);
        return getIsPublicContext() ? MetricSharePublicType.SharedPublic : getShareType(share);
    };

    const logDownloadError = (shareType: MetricShareTypeWithPublic, state: TransferState, error?: Error) => {
        const errorCategory = getErrorCategory(state, error);
        metrics.drive_download_errors_total.increment({
            type: errorCategory,
            shareType,
            initiator,
        });
    };

    const logSuccessRate = (shareType: MetricShareTypeWithPublic, state: TransferState, retry: boolean) => {
        metrics.drive_download_success_rate_total.increment({
            status: state === TransferState.Done ? 'success' : 'failure',
            retry: retry ? 'true' : 'false',
            shareType,
        });
    };

    const maybeLogUserError = (shareType: MetricShareTypeWithPublic, isError: boolean, error?: Error) => {
        if (isError && !isIgnoredErrorForReporting(error)) {
            if (Date.now() - lastErroringUserReport.current > REPORT_ERROR_USERS_EVERY) {
                metrics.drive_download_erroring_users_total.increment({
                    plan: user ? (user.isPaid ? 'paid' : 'free') : 'unknown',
                    shareType,
                });
                lastErroringUserReport.current = Date.now();
            }
            userSuccessMetrics.mark(UserAvailabilityTypes.coreFeatureError);
        }
    };

    const logDownloadMetrics = (
        shareType: MetricShareTypeWithPublic,
        state: TransferState,
        retry: boolean,
        error?: Error
    ) => {
        logSuccessRate(shareType, state, retry);
        // These 2 states are final Error states
        const isError = [TransferState.Error, TransferState.NetworkError].includes(state);
        if (isError) {
            logDownloadError(shareType, state, error);
        }
        maybeLogUserError(shareType, isError, error);
    };

    /*
     * For stateful downloads
     */
    const observe = (downloads: Download[]) => {
        for (const download of downloads) {
            if (isAbortError(download.error)) {
                continue;
            }
            // shareType is infered from the download rootShareId (each links are LinkDownload type)
            const shareType = getShareIdType(download.links[0]?.shareId);
            const key = getKey(download.id, download.retries || 0);
            // These 3 states are final (we omit skipped and cancelled)
            if ([TransferState.Done, TransferState.Error, TransferState.NetworkError].includes(download.state)) {
                if (!processed.has(key)) {
                    logDownloadMetrics(shareType, download.state, Boolean(download.retries), download.error);
                    setProcessed((prev) => new Set(prev.add(key)));
                }
            }
        }
    };

    /*
     * For non-stateful downloads (Preview)
     */
    const report = (shareId: string, state: TransferState.Done | TransferState.Error, error?: Error) => {
        if (isAbortError(error)) {
            return;
        }

        const shareType = getShareIdType(shareId);
        logDownloadMetrics(shareType, state, false, error);
    };

    return {
        observe,
        report,
    };
};

import { act, renderHook } from '@testing-library/react-hooks';

import metrics from '@proton/metrics';

import { TransferState } from '../../../components/TransferManager/transfer';
import { ShareType } from '../../_shares';
import useSharesState from '../../_shares/useSharesState';
import type { Download } from './interface';
import { getErrorCategory, useDownloadMetrics } from './useDownloadMetrics';

jest.mock('@proton/metrics', () => ({
    drive_download_success_rate_total: {
        increment: jest.fn(),
    },
    drive_download_errors_total: {
        increment: jest.fn(),
    },
    drive_download_erroring_users_total: {
        increment: jest.fn(),
    },
}));

jest.mock('../../_shares/useSharesState', () => ({
    __esModule: true,
    default: jest.fn(),
}));

const mockUseShareState = jest.mocked(useSharesState);

describe('getErrorCategory', () => {
    const testCases = [
        { state: TransferState.Error, error: { status: 503 }, expected: 'server_error', desc: 'unreachable error' },
        {
            state: TransferState.Error,
            error: { name: 'TimeoutError' },
            expected: 'server_error',
            desc: 'timeout error',
        },
        {
            state: TransferState.Error,
            error: { name: 'OfflineError' },
            expected: 'network_error',
            desc: 'offline error',
        },
        {
            state: TransferState.Error,
            error: { name: 'NetworkError' },
            expected: 'network_error',
            desc: 'network error',
        },
        { state: TransferState.NetworkError, error: {}, expected: 'network_error', desc: 'NetworkError state' },
        {
            state: TransferState.Error,
            error: { statusCode: 429 },
            expected: 'rate_limited',
            desc: 'rate limited error',
        },
        { state: TransferState.Error, error: { statusCode: 400 }, expected: '4xx', desc: '4xx error' },
        { state: TransferState.Error, error: { statusCode: 500 }, expected: '5xx', desc: '5xx error' },
        { state: TransferState.Error, error: {}, expected: 'unknown', desc: 'unknown error' },
    ];

    testCases.forEach(({ state, error, expected, desc }) => {
        it(`should return ${expected} for ${desc}`, () => {
            expect(getErrorCategory(state, error)).toBe(expected);
        });
    });
});

describe('useDownloadMetrics', () => {
    const mockGetShare = jest.fn();

    beforeEach(() => {
        jest.clearAllMocks();
        mockUseShareState.mockReturnValue({ getShare: mockGetShare } as any);
    });

    it('should observe downloads and update metrics for successful downloads', () => {
        mockGetShare.mockReturnValue({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownloads = [
            {
                id: '1',
                state: TransferState.Done,
                links: [{ shareId: 'share1' }],
                error: null,
            },
        ] as unknown as Download[];

        act(() => {
            result.current.observe(testDownloads);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledWith({
            status: 'success',
            retry: 'false',
            shareType: 'main',
        });
    });

    it('should observe downloads and update metrics for failed downloads', () => {
        mockGetShare.mockReturnValue({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownloads: Download[] = [
            {
                id: '2',
                state: TransferState.Error,
                links: [{ shareId: 'share2' }],
                error: { statusCode: 500 },
            },
        ] as unknown as Download[];

        act(() => {
            result.current.observe(testDownloads);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledWith({
            status: 'failure',
            retry: 'false',
            shareType: 'main',
        });

        expect(metrics.drive_download_errors_total.increment).toHaveBeenCalledWith({
            type: '5xx',
            initiator: 'download',
            shareType: 'main',
        });
    });

    it('should observe downloads and update metrics correctly for retried downloads', () => {
        mockGetShare.mockReturnValue({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownloads: Download[] = [
            {
                id: '2',
                state: TransferState.Error,
                links: [{ shareId: 'share2' }],
                error: { statusCode: 500 },
            },
        ] as unknown as Download[];

        act(() => {
            result.current.observe(testDownloads);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledWith({
            status: 'failure',
            retry: 'false',
            shareType: 'main',
        });

        expect(metrics.drive_download_errors_total.increment).toHaveBeenCalledWith({
            type: '5xx',
            initiator: 'download',
            shareType: 'main',
        });

        act(() => {
            const testDownloadsDone: Download[] = [
                {
                    id: '2',
                    state: TransferState.Done,
                    links: [{ shareId: 'share2' }],
                    error: null,
                    retries: 1,
                },
            ] as unknown as Download[];
            result.current.observe(testDownloadsDone);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledWith({
            status: 'success',
            retry: 'true',
            shareType: 'main',
        });
    });

    it('should not process the same download twice', () => {
        mockGetShare.mockReturnValue({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownload: Download = {
            id: '3',
            state: TransferState.Done,
            links: [{ shareId: 'share3' }],
            error: null,
        } as unknown as Download;

        act(() => {
            result.current.observe([testDownload]);
        });

        act(() => {
            result.current.observe([testDownload]);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledTimes(1);
    });

    it('should not handle multiple LinkDownload in a download', () => {
        mockGetShare.mockReturnValueOnce({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownload = {
            id: '4',
            state: TransferState.Done,
            links: [{ shareId: 'share4a' }, { shareId: 'share4b' }],
            error: null,
        } as unknown as Download;

        act(() => {
            result.current.observe([testDownload]);
        });

        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenCalledTimes(1);
        expect(metrics.drive_download_success_rate_total.increment).toHaveBeenNthCalledWith(1, {
            status: 'success',
            retry: 'false',
            shareType: 'main',
        });
    });

    it('should handle different error states', () => {
        mockGetShare.mockReturnValue({ type: ShareType.default });

        const { result } = renderHook(() => useDownloadMetrics('download'));

        const testDownloads: Download[] = [
            {
                id: '5',
                state: TransferState.NetworkError,
                links: [{ shareId: 'share5' }],
                error: { isNetwork: true },
            },
            {
                id: '6',
                state: TransferState.Error,
                links: [{ shareId: 'share6' }],
                error: null,
            },
        ] as unknown as Download[];

        act(() => {
            result.current.observe(testDownloads);
        });

        expect(metrics.drive_download_errors_total.increment).toHaveBeenCalledTimes(2);
        expect(metrics.drive_download_errors_total.increment).toHaveBeenCalledWith({
            type: 'network_error',
            initiator: 'download',
            shareType: 'main',
        });
        expect(metrics.drive_download_errors_total.increment).toHaveBeenCalledWith({
            type: 'unknown',
            initiator: 'download',
            shareType: 'main',
        });
    });

    it('should only report failed users every 5min', () => {
        jest.useFakeTimers().setSystemTime(new Date('2020-01-01 10:00:00'));
        mockGetShare.mockReturnValue({ type: ShareType.default });
        const { result } = renderHook(() => useDownloadMetrics('download'));

        act(() => {
            result.current.observe([
                {
                    id: '2',
                    state: TransferState.Error,
                    links: [{ shareId: 'share2' }],
                    error: { statusCode: 500 },
                },
            ] as unknown as Download[]);
        });
        expect(metrics.drive_download_erroring_users_total.increment).toHaveBeenCalledWith({
            plan: 'unknown',
            shareType: 'main',
        });

        // 1 min passed
        jest.useFakeTimers().setSystemTime(new Date('2020-01-01 10:01:00'));
        act(() => {
            result.current.observe([
                {
                    id: '234',
                    state: TransferState.Error,
                    links: [{ shareId: 'share234' }],
                    error: { statusCode: 500 },
                },
            ] as unknown as Download[]);
        });
        expect(metrics.drive_download_erroring_users_total.increment).toHaveBeenCalledTimes(1);

        // 4min and 1 second passed
        jest.useFakeTimers().setSystemTime(new Date('2020-01-01 10:05:01'));
        act(() => {
            result.current.observe([
                {
                    id: '789',
                    state: TransferState.Error,
                    links: [{ shareId: 'abc' }],
                    error: { statusCode: 500 },
                },
            ] as unknown as Download[]);
        });
        expect(metrics.drive_download_erroring_users_total.increment).toHaveBeenCalledTimes(2);
    });
});

import { useCallback, useRef } from 'react';

import { FILE_CHUNK_SIZE } from '@proton/shared/lib/drive/constants';

import { TransferState } from '../../../components/TransferManager/transfer';
import { isTransferFinished, isTransferPending, isTransferProgress } from '../../../utils/transfer';
import type { DownloadControls } from '../interface';
import type {
    Download,
    DownloadLinksProgresses,
    DownloadProgresses,
    UpdateCallback,
    UpdateFilter,
    UpdateState,
} from './interface';

export default function useDownloadControl(
    downloads: Download[],
    updateWithCallback: (idOrFilter: UpdateFilter, newState: UpdateState, callback: UpdateCallback) => void,
    removeFromQueue: (idOrFilter: UpdateFilter, callback: UpdateCallback) => void,
    clearQueue: () => void
) {
    // Controls keep references to ongoing downloads to have ability
    // to pause or cancel them.
    const controls = useRef<{ [id: string]: DownloadControls }>({});
    const progresses = useRef<DownloadProgresses>({});

    const add = (id: string, downloadControls: DownloadControls) => {
        controls.current[id] = downloadControls;
        progresses.current[id] = { progress: 0, links: {} };
    };

    const remove = (id: string) => {
        delete controls.current[id];
        delete progresses.current[id];
    };

    const getLinkProgress = (id: string, linkId: string) => {
        if (!progresses.current[id].links[linkId]) {
            progresses.current[id].links[linkId] = {
                progress: 0,
            };
        }
        return progresses.current[id].links[linkId];
    };

    const updateLinkSizes = (id: string, linkSizes: { [linkId: string]: number }) => {
        // Progress might be updated even when transfer is already finished and
        // thus progress is not here anymore. In such case it is OK to simply
        // ignore the call to not crash.
        if (progresses.current[id] === undefined) {
            return;
        }
        Object.entries(linkSizes || {}).forEach(([linkId, size]) => {
            getLinkProgress(id, linkId).total = size;
        });
    };

    const updateProgress = (id: string, linkIds: string[], increment: number) => {
        // Progress might be updated even when transfer is already finished and
        // thus progress is not here anymore. In such case it is OK to simply
        // ignore the call to not crash.
        if (progresses.current[id] === undefined) {
            return;
        }
        progresses.current[id].progress += increment;
        // Because increment can be float, some aritmetic operation can result
        // in -0.0000000001 which would be then displayed as -0 after rounding.
        if (progresses.current[id].progress < 0) {
            progresses.current[id].progress = 0;
        }

        linkIds.forEach((linkId) => (getLinkProgress(id, linkId).progress += increment));
    };

    const getProgresses = () =>
        Object.fromEntries(Object.entries(progresses.current).map(([linkId, { progress }]) => [linkId, progress]));

    const getLinksProgress = (): DownloadLinksProgresses =>
        Object.values(progresses.current).reduce((aggregatedLinks, { links }) => {
            // What if some link is downloaded more than once?
            // Probably very rare case which we can safely ignore. The worst case
            // scenario is that we show randomly progress of one download, but
            // thanks to browser caching it will not be that much off.
            return { ...aggregatedLinks, ...links };
        }, {});

    /**
     * calculateDownloadLoad returns based on progresses of ongoing downloads
     * how many data is currently being remaining to be downloaded.
     * If the size is not known yet (for example, folder which has not loaded
     * all children), it returns undefined. That should be taken as high load
     * and not start any other download for now.
     * Otherwise it returns number of remaining blocks of active transfers.
     */
    const calculateDownloadBlockLoad = (): number | undefined => {
        const progressingDownloads = downloads.filter(isTransferProgress);
        if (progressingDownloads.some(({ meta: { size } }) => size === undefined)) {
            return undefined;
        }
        return progressingDownloads.reduce((sum: number, download) => {
            const downloadedSize = progresses.current[download.id]?.progress || 0;
            return sum + Math.ceil(((download.meta.size as number) - downloadedSize) / FILE_CHUNK_SIZE);
        }, 0);
    };

    const pauseDownloads = useCallback(
        (idOrFilter: UpdateFilter) => {
            updateWithCallback(idOrFilter, TransferState.Paused, ({ id, state }) => {
                if (isTransferProgress({ state }) || isTransferPending({ state })) {
                    (controls.current[id] as DownloadControls)?.pause?.();
                }
            });
        },
        [updateWithCallback]
    );

    const resumeDownloads = useCallback(
        (idOrFilter: UpdateFilter) => {
            updateWithCallback(
                idOrFilter,
                ({ resumeState }) => {
                    return resumeState || TransferState.Progress;
                },
                ({ id }) => {
                    (controls.current[id] as DownloadControls)?.resume?.();
                }
            );
        },
        [updateWithCallback]
    );

    const cancelDownloads = useCallback(
        (idOrFilter: UpdateFilter) => {
            // Do not cancel already finished transfers.
            updateWithCallback(
                idOrFilter,
                ({ state }) => (isTransferFinished({ state }) ? state : TransferState.Canceled),
                ({ state, id }) => !isTransferFinished({ state }) && controls.current[id]?.cancel()
            );
        },
        [updateWithCallback]
    );

    const removeDownloads = useCallback(
        (idOrFilter: UpdateFilter) => {
            // We should never simply remove downloads, but cancel it first, so
            // it does not continue on background without our knowledge.
            cancelDownloads(idOrFilter);
            removeFromQueue(idOrFilter, ({ id }) => remove(id));
        },
        [removeFromQueue]
    );

    const clearDownloads = useCallback(() => {
        Object.entries(controls.current).map(([, downloadControls]) => downloadControls.cancel());
        controls.current = {};
        progresses.current = {};
        clearQueue();
    }, [clearQueue]);

    return {
        add,
        remove,
        updateLinkSizes,
        updateProgress,
        getProgresses,
        getLinksProgress,
        calculateDownloadBlockLoad,
        pauseDownloads,
        resumeDownloads,
        cancelDownloads,
        removeDownloads,
        clearDownloads,
    };
}
import { c } from 'ttag';
import type { ReadableStream } from 'web-streams-polyfill';

import { useApi } from '@proton/components';
import { queryFileRevision, queryFileRevisionThumbnail } from '@proton/shared/lib/api/drive/files';
import type {
    DriveFileBlock,
    DriveFileRevisionResult,
    DriveFileRevisionThumbnailResult,
} from '@proton/shared/lib/interfaces/drive/file';

import { TransferState } from '../../components/TransferManager/transfer';
import { logError } from '../../utils/errorHandling';
